  ('00000000-0000-4000-8000-000100000251', 593, 4, 'your strongest muscle and worst enemy is your mind. train it well.', 'assets/audio/quotes/fifty/q049.mp3', 0),
  ('00000000-0000-4000-8000-000100000252', 594, 4, 'don''t react. cut them off silently.', 'assets/audio/quotes/fifty/q050.mp3', 0),
  ('00000000-0000-4000-8000-000100000253', 595, 4, 'someone else''s progress doesn''t make yours any less.', 'assets/audio/quotes/fifty/q051.mp3', 0),
  ('00000000-0000-4000-8000-000100000254', 596, 4, 'don''t ever let the same people disappoint you twice.', 'assets/audio/quotes/fifty/q052.mp3', 0),
