  ('00000000-0000-4000-8000-00010000025b', 603, 4, 'embrace solitude as a time for reflection and self-discovery.', 'assets/audio/quotes/fifty/q059.mp3', 0),
  ('00000000-0000-4000-8000-00010000025c', 604, 4, 'not everyone you trust will be trustworthy.', 'assets/audio/quotes/fifty/q060.mp3', 0),
  ('00000000-0000-4000-8000-00010000025d', 605, 4, 'don''t be afraid to express vulnerability, it shows strength.', 'assets/audio/quotes/fifty/q061.mp3', 0),
